require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/clinic-fees.php';
define('HQ_BASE_URL','..');requireRole(['Admin']);$pdo=getDbConnection();$user=currentUser();$errors=[];$flash=(string)($_SESSION['fee_review_success']??'');unset($_SESSION['fee_review_success']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verifyCsrfToken($_POST['csrf_token']??null))$errors[]='Your session expired. Please try again.';
 elseif(!$pdo)$errors[]='Database unavailable.';
 else{try{reviewClinicFee($pdo,(int)$user['UserID'],(int)($_POST['request_id']??0),(string)($_POST['decision']??''));$_SESSION['fee_review_success']='Fee request reviewed.';header('Location: clinic-fees.php',true,303);exit;}catch(Throwable $e){error_log('Fee request review failed: '.$e->getMessage());$errors[]=$e instanceof PDOException?'We could not review this request.':$e->getMessage();}}
}
$requests=[];$today=date('Y-m-d');if($pdo){$today=(string)$pdo->query('SELECT CURDATE()')->fetchColumn();$requests=$pdo->query("SELECT f.*,c.ClinicName,u.FirstName,u.LastName FROM ClinicFeeRequests f JOIN Clinic c ON c.ClinicID=f.ClinicID JOIN Users u ON u.UserID=f.RequestedBy ORDER BY (f.Status='Pending') DESC,f.RequestID DESC LIMIT 100")->fetchAll();}
$isAdminDirectory=true;$pageTitle='Fee change requests - HealthQueue';require __DIR__.'/../includes/header.php';
