<?php if($r['Status']==='Pending'): ?><form method="post" class="mc-review-actions"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrfToken()) ?>"><input type="hidden" name="request_id" value="<?= (int)$r['RequestID'] ?>"><button class="btn btn-primary" name="decision" value="Approved"<?= $r['EffectiveDate']<$today?' disabled':'' ?>>Approve request</button><button class="btn btn-outline" name="decision" value="Declined">Decline</button></form><?php if($r['EffectiveDate']<$today): ?><p>The effective date has passed. Decline and request a new date.</p><?php endif; ?><?php endif; ?></div><span class="mc-fee-status mc-fee-<?= strtolower($state) ?>"><?= htmlspecialchars($state) ?></span></article><?php endforeach; ?><?php if(!$requests): ?><p>No fee change requests yet.</p><?php endif; ?></div></section></div></main>
